$I$ ens ordonné fini

$\forall i\in I\qquad V_i^\circ$ variété à bord [bord vide si $i$ minimal)

\[
\forall(i,j)\in I\times I,\quad j<i\qquad
\underset{\substack{\text{sous-}\\\text{variété à bord}}}{\partial_jV_i^\circ}\subset\partial V_i^\circ
\]
\diagram{\begin{tikzcd}
\partial_jV_i^\circ\arrow[r]&V_j^\circ
\end{tikzcd}}
\uline{fibration}

fibres des variétés à bord (variétés \inserted{sans bord} si $j$ prédécesseur de $i$)

\diagram{\begin{tikzcd}
\partial V_i^\circ=\displaystyle\bigcup_{\substack{j\in\Phi_i\\\text{ens des facettes de }i}}\underbracket{\partial_jV_i^\circ}\arrow[dr] &\\
&V_j^\circ
\end{tikzcd}}
\[
\partial(\partial_jV_i^\circ)=[(\partial_jV_i^\circ)|\partial V_j^\circ]\cup
\underbracket{\partial_{\unsure{i|\ell}/j}(\partial_jV_i^\circ)}_{\substack{\text{fibré des}\\\text{bords}}}
\]
\[
\partial(\partial_jV_i^\circ)=\bigcup_{k\in\Phi_j}\underbracket{(\partial_jV_i^\circ)|\partial_kV_j^\circ)}_{\text{fibré sur }V_k^\circ}
\cup\underbracket{\partial_{i/j}(\partial_jV_i^\circ)}_{\substack{\text{fibré sur}\\V_j^\circ}}
=\left(\bigcup_{k<j}\underbrace{(\partial_jV_i^\circ|\partial_kV_j^\circ)}_{\text{fibré sur }V_{\unsure{k|h}}^\circ}\right)
\cup\underbracket{\partial_{\unsure{0|i}/(j)}\partial V_i^\circ}_{\text{fibré sur }V_j^\circ}
\]
