\[
\partial(\partial_{j'}V_i^\circ)=\left(\bigcup_{k<j'}\partial_{j'}V_i^\circ|\partial_kV_{\unsure{j'|j}}^\circ\right)\cup
\underbracket{\partial_{i/j'}V_i^\circ}_{\substack{\text{vide si }j'\text{ préd.}\\\text{de }i}}
\]

